#include "WuaDVI.h"

/* Library-internal, generated by scripts/library_build.py which library.json
 * declares as this library's extraScript.  Reaching it from here proves the
 * hook ran and put its output on the library's include path.  If it did not,
 * this include fails and the spike has its answer. */
#include "wuadvi_rp_payload.h"

#ifndef WUADVI_RP_PAYLOAD_PRESENT
#error "WuaDVI-lib: the library build hook did not generate the RP payload header"
#endif

const char *wuadvi_rp_firmware_version(void) {
    return WUADVI_RP_PAYLOAD_VERSION;
}
